#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Credentials setup for willianjusten.com.br (issue #281).
# Values land in .env.local (gitignored) and in the Vercel project env.
# Run from the repo root: ./scripts/setup-credentials.sh

ENV_FILE=".env.local"
VERCEL_SCOPE="willian-justens-projects"
VERCEL_PROJECT="willianjusten-site"

# vercel_env NAME VALUE ENVIRONMENT... upserts a Sensitive env var in each
# Vercel environment. Records a manual follow-up when the CLI call fails.
vercel_env() {
  local name="$1" value="$2" environment; shift 2
  for environment in "$@"; do
    if printf '%s' "$value" | vercel env add "$name" -e "$environment" --sensitive --force --yes \
        --scope "$VERCEL_SCOPE" >/dev/null 2>&1; then
      printf '  %s✓ set%s Vercel %s → %s\n' "$GREEN" "$RESET" "$name" "$environment"
    else
      SKIPPED+=("Vercel env $name ($environment): vercel env add $name -e $environment --sensitive")
      warn "could not set Vercel $name for $environment; set it later"
    fi
  done
}

run_wizard() {

TOTAL_STAGES=6

banner "willianjusten.com.br credentials"

# ── 1. Vercel link ─────────────────────────────────────────────────────────
stage "Vercel: link this repo to the project"
say "The wizard writes env vars through the Vercel CLI, so the repo must be"
say "linked to the '$VERCEL_PROJECT' project under '$VERCEL_SCOPE'."
if ! command -v vercel >/dev/null 2>&1; then
  warn "Vercel CLI not found. Install it (npm i -g vercel), then re-run."
  exit 1
fi
if [[ -f .vercel/project.json ]] && grep -q "\"projectName\":\"$VERCEL_PROJECT\"" .vercel/project.json; then
  note "Already linked to $VERCEL_PROJECT."
else
  confirm "Run 'vercel link' to $VERCEL_PROJECT now?" || exit 1
  vercel link --yes --project "$VERCEL_PROJECT" --scope "$VERCEL_SCOPE"
fi
pause

# ── 2. Neon ────────────────────────────────────────────────────────────────
stage "Neon: database project and branches"
say "We'll create a new Neon project with two branches: the default one for"
say "production and a 'dev' one for local and preview deploys."
open_url "https://console.neon.tech/app/projects"
step "Click 'New project'. Name: willianjusten-site."
step "Region: AWS South America (São Paulo), sa-east-1, next to Vercel's gru1."
step "Create it. The default branch is called 'main' or 'production'."
step "Sidebar → Branches → 'New branch', name 'dev', parent = the default branch."
note "If the project already came with a 'development' branch, use that instead of creating 'dev'."
pause
step "Project dashboard → 'Connect'. Pick the DEFAULT branch, turn 'Connection pooling' on,"
step "and copy the connection string (postgresql://...)."
ask_secret NEON_PRODUCTION_URL "Paste the default (production) branch connection string:"
step "In the same 'Connect' dialog, switch the branch to 'dev' and copy that string."
ask_secret DATABASE_URL "Paste the dev branch connection string:"
write_env DATABASE_URL "$DATABASE_URL"
vercel_env DATABASE_URL "$NEON_PRODUCTION_URL" production
vercel_env DATABASE_URL "$DATABASE_URL" preview
pause

# ── 3. IP hash secret ──────────────────────────────────────────────────────
stage "IP hash secret"
say "Visitor IPs are hashed with this secret before they touch the database."
existing_ip_secret=$(_existing IP_HASH_SECRET || true)
if [[ -n "$existing_ip_secret" ]]; then
  note "Keeping the existing IP_HASH_SECRET from $ENV_FILE."
  IP_HASH_SECRET="$existing_ip_secret"
else
  IP_HASH_SECRET=$(openssl rand -hex 32)
  note "Generated a new 64-character secret."
fi
write_env IP_HASH_SECRET "$IP_HASH_SECRET"
vercel_env IP_HASH_SECRET "$IP_HASH_SECRET" production preview
pause

# ── 4. Twitch / IGDB ───────────────────────────────────────────────────────
stage "IGDB: Twitch developer app"
say "IGDB uses Twitch credentials. Two-factor auth must be on first."
open_url "https://www.twitch.tv/settings/security"
step "Under 'Two-Factor Authentication', enable it if it is not already on."
pause
open_url "https://dev.twitch.tv/console/apps/create"
step "Name: willianjusten-site (must be unique on Twitch; add a suffix if taken)."
step "OAuth Redirect URLs: http://localhost  (IGDB never uses it)."
step "Category: Website Integration. Client Type: Confidential. Click Create."
step "Open the app ('Manage'), copy the Client ID, then click 'New Secret' and copy it."
ask IGDB_CLIENT_ID "Paste the Client ID:"
ask_secret IGDB_CLIENT_SECRET "Paste the Client Secret:"
write_env IGDB_CLIENT_ID "$IGDB_CLIENT_ID"
write_env IGDB_CLIENT_SECRET "$IGDB_CLIENT_SECRET"
note "Checking the credentials against Twitch and IGDB..."
igdb_token=$(printf 'client_id=%s&client_secret=%s&grant_type=client_credentials' "$IGDB_CLIENT_ID" "$IGDB_CLIENT_SECRET" \
  | curl -s -X POST --data @- https://id.twitch.tv/oauth2/token \
  | sed -n 's/.*"access_token":"\([^"]*\)".*/\1/p' || true)
if [[ -z "$igdb_token" ]]; then
  warn "Twitch did not return a token. Check the Client ID and Secret."
  SKIPPED+=("IGDB credentials did not verify; re-run the wizard")
else
  igdb_status=$(printf 'fields name; search "alan wake 2"; limit 1;' \
    | curl -s -o /dev/null -w '%{http_code}' -X POST --data @- https://api.igdb.com/v4/games \
        -H @<(printf 'Client-ID: %s\nAuthorization: Bearer %s\n' "$IGDB_CLIENT_ID" "$igdb_token") || true)
  if [[ "$igdb_status" == "200" ]]; then
    printf '  %s✓ IGDB answered a search%s\n' "$GREEN" "$RESET"
  else
    warn "IGDB returned HTTP $igdb_status."
    SKIPPED+=("IGDB query returned HTTP $igdb_status; check the app")
  fi
fi
vercel_env IGDB_CLIENT_ID "$IGDB_CLIENT_ID" production preview
vercel_env IGDB_CLIENT_SECRET "$IGDB_CLIENT_SECRET" production preview
pause

# ── 5. Cloudinary ──────────────────────────────────────────────────────────
stage "Cloudinary: API keys"
say "Use the account that backs photos.willianjusten.com.br."
open_url "https://console.cloudinary.com/settings/api-keys"
step "The page shows the Cloud name at the top and a table of API keys."
step "Copy the Cloud name, then the API Key and API Secret of a key (or 'Generate New API Key')."
ask CLOUDINARY_CLOUD_NAME "Paste the Cloud name:"
ask CLOUDINARY_API_KEY "Paste the API Key:"
ask_secret CLOUDINARY_API_SECRET "Paste the API Secret:"
write_env CLOUDINARY_CLOUD_NAME "$CLOUDINARY_CLOUD_NAME"
write_env CLOUDINARY_API_KEY "$CLOUDINARY_API_KEY"
write_env CLOUDINARY_API_SECRET "$CLOUDINARY_API_SECRET"
note "Checking the credentials against the Cloudinary Admin API..."
cloudinary_status=$(curl -s -o /dev/null -w '%{http_code}' \
  --config <(printf 'user = "%s:%s"\n' "$CLOUDINARY_API_KEY" "$CLOUDINARY_API_SECRET") \
  "https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/resources/image?max_results=1" || true)
if [[ "$cloudinary_status" == "200" ]]; then
  printf '  %s✓ Cloudinary accepted the key%s\n' "$GREEN" "$RESET"
else
  warn "Cloudinary returned HTTP $cloudinary_status."
  SKIPPED+=("Cloudinary check returned HTTP $cloudinary_status; verify the keys")
fi
vercel_env CLOUDINARY_CLOUD_NAME "$CLOUDINARY_CLOUD_NAME" production preview
vercel_env CLOUDINARY_API_KEY "$CLOUDINARY_API_KEY" production preview
vercel_env CLOUDINARY_API_SECRET "$CLOUDINARY_API_SECRET" production preview
pause

# ── 6. Odesli ──────────────────────────────────────────────────────────────
stage "Odesli (song.link): optional API key"
say "Odesli turns one song link into YouTube Music, Spotify and Apple Music links."
note "Testing the free endpoint without a key..."
odesli_status=$(curl -s -o /dev/null -w '%{http_code}' \
  "https://api.song.link/v1-alpha.1/links?url=https%3A%2F%2Fopen.spotify.com%2Ftrack%2F4PTPZeJlK1rYlYr6bf11hk&userCountry=BR" || true)
if [[ "$odesli_status" == "200" ]]; then
  printf '  %s✓ Works without a key (about 10 requests per minute)%s\n' "$GREEN" "$RESET"
  if confirm "Do you already have an Odesli key you want to store anyway?"; then
    ask_secret ODESLI_API_KEY "Paste the Odesli API key:"
    write_env ODESLI_API_KEY "$ODESLI_API_KEY"
    vercel_env ODESLI_API_KEY "$ODESLI_API_KEY" production preview
  fi
else
  warn "The keyless endpoint returned HTTP $odesli_status, so a key is needed."
  if confirm "Do you already have an Odesli key?"; then
    ask_secret ODESLI_API_KEY "Paste the Odesli API key:"
    write_env ODESLI_API_KEY "$ODESLI_API_KEY"
    vercel_env ODESLI_API_KEY "$ODESLI_API_KEY" production preview
  else
    step "Opening an email draft to request a key. Send it, then re-run this wizard when it arrives."
    open_url "mailto:developers@song.link?subject=API%20key%20request&body=Hi%2C%20I%27d%20like%20an%20Odesli%20API%20key%20for%20my%20personal%2C%20non-commercial%20site%20willianjusten.com.br%20to%20resolve%20song%20links%20for%20a%20small%20curated%20list.%20Thanks!"
    SKIPPED+=("Odesli API key: requested by email; re-run the wizard to store it")
  fi
fi
pause

finish
}

run_wizard "$@"; exit
